(() => {
  window.__dwCheck = (name, ok, detail) => { if (!ok) console.error('[craft picker check] ' + name + ' failed: ' + detail); return (ok ? 'PASS ' : 'FAIL ') + name + ': ' + detail; };
  const game = window.DRIFTWING;
  const log = { crashes: [], notes: [], changes: [], skins: [] };
  window.__dwPick = log;
  game.ctx.bus.onTyped('softCrash', (payload) => log.crashes.push({ time: game.state.time.elapsed, craft: payload.craft, reason: payload.reason }));
  game.ctx.bus.on('notify', (payload) => log.notes.push(String(payload && payload.text)));
  game.ctx.bus.onTyped('craftChanged', (payload) => log.changes.push({ time: game.state.time.elapsed, craft: payload.craft }));
  game.ctx.bus.on('craft:skinChanged', (payload) => log.skins.push(payload));
  game.ctx.settings.reset('craftFavorites');
  game.ctx.settings.reset('craftSkins');
  document.getElementById('ui-root').classList.remove('dw-idle');
  return 'run on V2 (a dev server or any build with ?debug=1): the craft picker, favorites, skins and situational spawns';
})()

(() => {
  const game = window.DRIFTWING;
  const registry = game.ctx.craftRegistry;
  const picker = game.ctx.systems.ui.craftPicker;
  picker.refresh();
  const state = picker.getState();
  const expected = registry.groups().map((group) => ({ group: group.id, craft: group.craft.filter((entry) => registry.has(entry.id)).map((entry) => entry.id) })).filter((group) => group.craft.length > 0);
  const shown = state.strip.flatMap((group) => group.craft);
  const installed = registry.list().filter((entry) => entry.available).map((entry) => entry.id);
  const favorites = game.ctx.settings.get('craftFavorites');
  const keyErrors = shown.filter((id) => state.keys[id] !== (favorites.indexOf(id) >= 0 ? (favorites.indexOf(id) === 9 ? '0' : String(favorites.indexOf(id) + 1)) : ''));
  const separators = document.querySelectorAll('#dw-craft-picker .dw-craft-separator').length;
  const strip = document.getElementById('dw-craft-picker').getBoundingClientRect();
  const compass = document.getElementById('dw-compass-strip').getBoundingClientRect();
  return [
    window.__dwCheck('the strip shows the installed craft in their groups, in catalog group order', JSON.stringify(state.strip) === JSON.stringify(expected), JSON.stringify(state.strip)),
    window.__dwCheck('every installed craft is shown and nothing else', shown.length === installed.length && installed.every((id) => shown.includes(id)), shown.join(', ')),
    window.__dwCheck('a hairline between groups, the roster button at the end', separators === expected.length - 1 && document.querySelector('#dw-craft-picker > :last-child').classList.contains('dw-craft-roster-button'), separators + ' separators'),
    window.__dwCheck('each craft shows its favorite key', keyErrors.length === 0, JSON.stringify(state.keys)),
    window.__dwCheck('the strip packs tighter from 11 craft only', state.dense === (shown.length >= 11), shown.length + ' craft, dense ' + state.dense),
    window.__dwCheck('the strip clears the compass at ' + window.innerWidth + ' px', window.innerWidth < 1280 || strip.right + 4 <= compass.left, 'strip right ' + Math.round(strip.right) + ', compass left ' + Math.round(compass.left)),
  ].join(' | ');
})()

(() => {
  const game = window.DRIFTWING;
  const flight = game.ctx.systems.flight;
  const pressed = document.querySelector('#dw-craft-picker .dw-craft-button[aria-pressed="true"]');
