(async () => {
  const game = window.DRIFTWING;
  const settings = game.ctx.settings;
  const picker = game.ctx.systems.ui.craftPicker;
  const frame = () => new Promise((resolve) => setTimeout(resolve, 60));
  document.querySelector('#dw-craft-picker .dw-craft-roster-button').click();
  await frame();
  const panel = document.getElementById('dw-craft-panel');
  const opened = picker.isOpen() && !panel.hidden && document.querySelector('.dw-craft-roster-button').getAttribute('aria-expanded') === 'true';
  const rows = [...panel.querySelectorAll('.dw-roster-row')].map((row) => row.dataset.craft);
  const shown = picker.getState().strip.flatMap((group) => group.craft);
  // The slot menu: the jet onto key 0 (the spaceplane, its occupant, moves to the jet's key 3).
  const menu = panel.querySelector('.dw-roster-row[data-craft="jet"] .dw-roster-slot');
  menu.value = '9';
  menu.dispatchEvent(new Event('change', { bubbles: true }));
  await frame();
  const afterMenu = settings.get('craftFavorites');
  const jetKey = picker.getState().keys.jet;
  // Drag the glider from the roster onto key 5 (the wingsuit swaps to the glider's key 1).
  const transfer = new DataTransfer();
  const gliderRow = panel.querySelector('.dw-roster-row[data-craft="glider"]');
  const slot5 = panel.querySelector('.dw-fav-slot[data-slot="4"]');
  gliderRow.dispatchEvent(new DragEvent('dragstart', { bubbles: true, dataTransfer: transfer }));
  slot5.dispatchEvent(new DragEvent('dragover', { bubbles: true, cancelable: true, dataTransfer: transfer }));
  slot5.dispatchEvent(new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer: transfer }));
  gliderRow.dispatchEvent(new DragEvent('dragend', { bubbles: true, dataTransfer: transfer }));
  await frame();
  const afterDrag = settings.get('craftFavorites');
  // Drag slot 2 (the bush plane) onto slot 4 (the helicopter): they swap.
  const swap = new DataTransfer();
  const slot2 = panel.querySelector('.dw-fav-slot[data-slot="1"]');
  const slot4 = panel.querySelector('.dw-fav-slot[data-slot="3"]');
  slot2.dispatchEvent(new DragEvent('dragstart', { bubbles: true, dataTransfer: swap }));
  slot4.dispatchEvent(new DragEvent('dragover', { bubbles: true, cancelable: true, dataTransfer: swap }));
  slot4.dispatchEvent(new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer: swap }));
  slot2.dispatchEvent(new DragEvent('dragend', { bubbles: true, dataTransfer: swap }));
  await frame();
  const afterSwap = settings.get('craftFavorites');
  // Clear key 6 (the FPV drone) with its x.
  panel.querySelector('.dw-fav-slot[data-slot="5"] .dw-fav-clear').click();
  await frame();
  const afterClear = settings.get('craftFavorites');
  window.__dwPickFavorites = afterClear;
  return [
    window.__dwCheck('the roster button opens the roster panel', opened, 'open ' + picker.isOpen()),
    window.__dwCheck('the roster lists the installed craft only', rows.length === shown.length && rows.every((id) => shown.includes(id)), rows.join(', ')),
    window.__dwCheck("the slot menu puts the jet on key 0; the spaceplane takes the jet's key 3", afterMenu[9] === 'jet' && afterMenu[2] === 'spaceplane' && jetKey === '0', JSON.stringify(afterMenu)),
    window.__dwCheck("a craft dragged onto key 5 takes it; the wingsuit moves to the glider's key 1", afterDrag[4] === 'glider' && afterDrag[0] === 'wingsuit', JSON.stringify(afterDrag)),
    window.__dwCheck('a slot dragged onto another swaps them', afterSwap[1] === 'helicopter' && afterSwap[3] === 'bushplane', JSON.stringify(afterSwap)),
    window.__dwCheck("a slot's x clears it", afterClear[5] === null, JSON.stringify(afterClear)),
  ].join(' | ');
})()

(() => {
  const notes = window.__dwPick.notes;
