(() => {
  const favorites = window.DRIFTWING.ctx.settings.get('craftFavorites');
  const registry = window.DRIFTWING.ctx.craftRegistry;
  const craft = window.DRIFTWING.ctx.systems.flight.getCraft();
  const flyable = favorites.filter((id) => id && registry.has(id));
  return window.__dwCheck('craftNext from the last key wraps to the first flyable favorite, skipping empty and uninstalled slots', craft === flyable[0], craft + ' (favorites ' + JSON.stringify(favorites) + ')');
})()

(async () => {
  const game = window.DRIFTWING;
  const registry = game.ctx.craftRegistry;
  const picker = game.ctx.systems.ui.craftPicker;
  const frame = (ms = 60) => new Promise((resolve) => setTimeout(resolve, ms));
  const standIn = !registry.has('eagle');
  if (standIn) {
    const glider = registry.get('glider');
    registry.register({ ...glider, id: 'eagle', name: 'Eagle / Dragon', skins: { default: 'eagle', list: [{ id: 'eagle', name: 'Eagle' }, { id: 'dragon', name: 'Dragon' }] } });
  }
  picker.update(10);
  await frame();
  const state = picker.getState();
  const creature = state.strip.find((group) => group.group === 'creature');
  const module = registry.get('eagle');
  const other = module.skins.list.find((skin) => skin.id !== module.skins.default);
  picker.openPanel('eagle');
  await frame();
  const panel = document.getElementById('dw-craft-panel');
  const row = panel.querySelector('.dw-roster-row[data-craft="eagle"]');
  const skinBox = row ? row.nextElementSibling : null;
  const underCraft = skinBox && skinBox.classList.contains('dw-roster-skins') && skinBox.querySelectorAll('.dw-roster-skin').length === module.skins.list.length;
  picker.select('eagle');
  await frame(2500);
  skinBox.querySelector('.dw-roster-skin[data-skin="' + other.id + '"]').click();
  await frame(400);
  const stored = game.ctx.settings.get('craftSkins').eagle;
  const checked = skinBox.querySelector('.dw-roster-skin[aria-checked="true"]');
  const event = window.__dwPick.skins.find((payload) => payload.craft === 'eagle' && payload.skin === other.id);
  skinBox.querySelector('.dw-roster-skin[data-skin="' + module.skins.default + '"]').click();
  await frame(400);
  const restored = game.ctx.settings.get('craftSkins').eagle;
  picker.closePanel();
  return [
    window.__dwCheck('a craft module registered after boot joins the strip in its group (' + (standIn ? 'a stand-in eagle module' : "the eagle's module") + ')', creature && creature.craft.includes('eagle'), JSON.stringify(state.strip)),
    window.__dwCheck('the skins sit right under the eagle in the roster', underCraft, skinBox ? skinBox.className : 'none'),
    window.__dwCheck('choosing a skin stores it and the flying eagle switches skin', stored === other.id && checked && checked.dataset.skin === other.id && Boolean(event), 'stored ' + stored + ', event ' + JSON.stringify(event || null)),
    window.__dwCheck("the default skin is stored as ''", restored === '', JSON.stringify(restored)),
  ].join(' | ');
})()

(async () => {
  const game = window.DRIFTWING;
  const registry = game.ctx.craftRegistry;
  const picker = game.ctx.systems.ui.craftPicker;
  const log = window.__dwPick;
  const results = [];
  const ids = registry.list().filter((entry) => entry.available).map((entry) => entry.id);
  for (const id of ids) {
    const before = log.crashes.length;
    const changedAt = log.changes.length;
    picker.select(id);
    await new Promise((resolve) => setTimeout(resolve, 6000));
    const position = game.state.player.position;
    results.push({ id, flying: game.ctx.systems.flight.getCraft(), changed: log.changes.slice(changedAt).some((change) => change.craft === id) || game.ctx.systems.flight.getCraft() === id, crashes: log.crashes.slice(before), finite: [position.x, position.y, position.z].every(Number.isFinite) });
  }
  const bad = results.filter((result) => result.flying !== result.id || !result.changed || result.crashes.length > 0 || !result.finite);
  return window.__dwCheck('every installed craft chosen in the picker spawns in a sensible state (no soft crash in the 6 s after the switch)', bad.length === 0, results.map((result) => result.id + (result.crashes.length ? ' CRASH ' + result.crashes[0].reason : ' ok')).join(', '));
})()

(async () => {
  const game = window.DRIFTWING;
  const registry = game.ctx.craftRegistry;
  const picker = game.ctx.systems.ui.craftPicker;
  const glider = registry.get('glider');
  const added = [];
  for (const entry of registry.catalog) {
    if (registry.has(entry.id)) continue;
    registry.register({ ...glider, id: entry.id, name: entry.name });
    added.push(entry.id);
  }
  picker.update(10);
  await new Promise((resolve) => setTimeout(resolve, 100));
  const state = picker.getState();
  const strip = document.getElementById('dw-craft-picker').getBoundingClientRect();
  const compass = document.getElementById('dw-compass-strip').getBoundingClientRect();
  const count = state.strip.reduce((sum, group) => sum + group.craft.length, 0);
  return [
    window.__dwCheck('all 14 craft in the six groups (' + added.length + ' stand-in modules)', count === 14 && JSON.stringify(state.strip.map((group) => group.group)) === JSON.stringify(['planes', 'rotor', 'human', 'lighterThanAir', 'creature', 'space']), JSON.stringify(state.strip)),
    window.__dwCheck('14 craft pack into the dense strip, clear of the compass at ' + window.innerWidth + ' px', state.dense && (window.innerWidth < 1280 || strip.right + 4 <= compass.left), 'strip ' + Math.round(strip.left) + '-' + Math.round(strip.right) + ', compass left ' + Math.round(compass.left)),
  ].join(' | ');
})()
